function lgEnhance(svg,active,distance){const ns='http://www.w3.org/2000/svg',sig=[...active].sort().join(',')+'|'+S.graphMode+'|'+S.graphDepth+'|t',fresh=S._lgSig!==sig;S._lgSig=sig;const st=document.createElementNS(ns,'style');st.textContent=LG_CSS;svg.prepend(st);const edges=[...svg.querySelectorAll('.lg-edge')],nodes=[...svg.querySelectorAll('.lg-node')];if(fresh&&!lgReduced())svg.classList.add('lg-anim');nodes.forEach(g=>g.style.setProperty('--d',((distance.get(g.dataset.id)||0)*.1)+'s'));edges.forEach((p,i)=>p.style.setProperty('--d',(i*.03)+'s'));lgHover(svg,nodes,edges);lgBindNodes(svg,nodes);const down=new Set(walk(S.selected,true));lgParticles(svg,'.lg-edge',p=>(p.dataset.from===S.selected||down.has(p.dataset.from))&&down.has(p.dataset.to)?1.6:3.2)}
function lgEnhanceCols(svg){const ns='http://www.w3.org/2000/svg',edges=[...svg.querySelectorAll('.lg-edge')],nodes=[...svg.querySelectorAll('.lg-node')],rows=[...svg.querySelectorAll('.col-row')],sig='c|'+edges.map(p=>p.dataset.src+'>'+p.dataset.tgt).join(','),fresh=S._lgSig!==sig;S._lgSig=sig;const st=document.createElementNS(ns,'style');st.textContent=LG_CSS;svg.prepend(st);if(fresh&&!lgReduced())svg.classList.add('lg-anim');nodes.forEach((g,i)=>g.style.setProperty('--d',(i*.12)+'s'));edges.forEach((p,i)=>p.style.setProperty('--d',(.1+i*.05)+'s'));lgHover(svg,nodes,edges);lgBindNodes(svg,nodes);const labs=[...svg.querySelectorAll('.lg-lab')],paint=col=>{const linked=new Set();if(col)edges.forEach(p=>{const hit=p.dataset.src===col||p.dataset.tgt===col;p.classList.toggle('lg-hot',hit);p.classList.toggle('lg-dim',!hit);if(hit){linked.add(p.dataset.src);linked.add(p.dataset.tgt)}});else edges.forEach(p=>p.classList.remove('lg-hot','lg-dim'));labs.forEach(l=>{const hit=!!col&&(l.dataset.src===col||l.dataset.tgt===col);l.classList.toggle('lg-dim',!!col&&!hit)});rows.forEach(r=>r.classList.toggle('lg-hot',!!col&&(r.dataset.col===col||linked.has(r.dataset.col))));rows.forEach(r=>r.classList.toggle('lg-pin',!!S.colPin&&r.dataset.col===S.colPin))};rows.forEach(r=>{r.addEventListener('mouseenter',()=>paint(r.dataset.col));r.addEventListener('mouseleave',()=>paint(S.colPin));r.addEventListener('click',e=>{e.stopPropagation();S.colPin=S.colPin===r.dataset.col?null:r.dataset.col;paint(S.colPin)});r.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.stopPropagation();e.preventDefault();S.colPin=S.colPin===r.dataset.col?null:r.dataset.col;paint(S.colPin)}})});paint(S.colPin);lgParticles(svg,'.lg-edge',p=>S.colPin&&(p.dataset.src===S.colPin||p.dataset.tgt===S.colPin)?1.6:3.2)}
function neoRecolor(svg){const m={'#1A1A1A':'--surface','#FAFAF8':'--ink','#2C2C2C':'--line','#738694':'--muted','#edf1f4':'--line','#126c59':'--ok-ink','#315da4':'--link','#087f8c':'--ink','#f7fafc':'--surface','#526779':'--muted','#607789':'--muted','#607383':'--muted','#8494a1':'--muted','#76cdb7':'--ink','#7fa8ff':'--ink','#a995ff':'--ink','#00FF9C':'--blue'};svg.querySelectorAll('*').forEach(el=>['fill','stroke'].forEach(k=>{const v=el.getAttribute(k);if(v&&m[v])el.setAttribute(k,cv(m[v],v))}))}
function card(label,val,icon,foot,lead){return '<div class="stat-card'+(lead?' lead':'')+'"><div class="stat-top"><span>'+label+'</span></div><div class="stat-value">'+val+'</div><div class="stat-foot">'+foot+'</div></div>'}
function metricLink(label,value,icon,foot,view){return '<button type="button" class="metric-card-link" data-view="'+esc(view)+'" aria-label="Open '+esc(view)+' for '+esc(label)+'">'+card(label,value,icon,foot)+'</button>'}
function findingText(){const r=V.find(e=>e.state==='REFUTED_FOR_RUN'),run=r&&R.find(x=>x.id===r.run),ob=V.filter(e=>e.state==='OBSERVED').length;if(!V.length)return 'No evidence records yet.';return r?'<strong>'+esc(r.source)+' → '+esc(r.target)+'</strong> is refuted for '+esc(r.run)+(run&&run.status==='FAILED'?', a failed run':'')+'. '+ob+' of '+V.length+' dependencies are observed.':ob+' of '+V.length+' dependencies are observed. None is refuted for a run.'}
function evidenceStrip(){const c={OBSERVED:0,POSSIBLE:0,REFUTED_FOR_RUN:0,UNKNOWN:0};V.forEach(e=>{if(c[e.state]!==undefined)c[e.state]++});const t=V.length;if(!t)return '<div class="evidence-strip" role="img" aria-label="No evidence records"><i style="flex:1"></i></div>';const cls={OBSERVED:'s-observed',POSSIBLE:'s-possible',REFUTED_FOR_RUN:'s-refuted',UNKNOWN:'s-unknown'};return '<div class="evidence-strip" role="img" aria-label="'+c.OBSERVED+' observed, '+c.POSSIBLE+' possible, '+c.REFUTED_FOR_RUN+' refuted for a run, '+c.UNKNOWN+' unknown">'+Object.keys(c).filter(k=>c[k]).map(k=>'<i class="'+cls[k]+'" style="flex:'+c[k]+'"></i>').join('')+'</div>'}
function notice(t,d){return '<div class="notice"><span class="notice-icon" aria-hidden="true">ⓘ</span><div><strong>'+t+'</strong> '+d+'</div></div>'}
function metadataFieldCatalog(){if(S._metadataFieldCatalog)return S._metadataFieldCatalog;const fields=[{key:'__qualified_name',label:'Qualified name',get:a=>a.path||a.qualified_name},{key:'__asset_type',label:'Asset type',get:a=>a.type||a.asset_type||a.metadata?.asset_type||a.kind},{key:'__description',label:'Description',get:a=>a.description||a.metadata?.description},{key:'__owner',label:'Owner',get:a=>{const v=a.owner||a.owner_name||a.metadata?.owner;return /^unassigned$/i.test(String(v||'').trim())?'':v}},{key:'__tags',label:'Tags / labels',get:a=>a.metadata?.tags||a.metadata?.labels||a.metadata?.topics||a.tags},{key:'__source_domain',label:'Source / domain',get:a=>a.domain||a.metadata?.domain||a.metadata?.business_domain||a.repository||a.metadata?.repository||a.source_system||a.metadata?.source_system||a.schema}];const excluded=new Set(['id','name','path','qualified_name','schema','schema_name','kind','asset_kind','type','asset_type','description','owner','owner_name','tags','labels','topics','domain','business_domain','namespace','repository','source_system','trust','trust_status','certification','certification_status','columns','column_lineage','column_mappings','raw_payload','raw_event','metadata','rows','row_count','column_count','quality','quality_score']);const keys=[...new Set(A.flatMap(a=>[...Object.keys(a),...Object.keys(a.metadata&&typeof a.metadata==='object'?a.metadata:{})]))].filter(k=>!excluded.has(k.toLowerCase())&&!/token|secret|password|credential/i.test(k)).sort((a,b)=>a.localeCompare(b,undefined,{sensitivity:'base'}));keys.forEach(key=>fields.push({key:'meta:'+key,label:key.replace(/[_-]+/g,' '),get:a=>a[key]??(a.metadata&&typeof a.metadata==='object'?a.metadata[key]:null)}));S._metadataFieldCatalog=fields;return fields;}function metadataValuePresent(v){return v!=null&&(typeof v==='string'?v.trim()!=='' : Array.isArray(v)?v.length>0:typeof v==='object'?Object.keys(v).length>0:true);}function metadataCompleteness(a){const fields=metadataFieldCatalog(),present=fields.filter(f=>metadataValuePresent(f.get(a))&&!(f.key==='__tags'&&Array.isArray(f.get(a))&&!f.get(a).length));return{score:fields.length?Math.round(present.length/fields.length*100):0,present:present.map(f=>f.label),missing:fields.filter(f=>!present.some(p=>p.key===f.key)).map(f=>f.label),total:fields.length,recorded:present.length};}function completenessCell(a){const c=metadataCompleteness(a);return '<span class="pill '+(c.score>=80?'mint':c.score>=50?'blue':'amber')+'">'+c.score+'%</span><div class="subline">'+c.recorded+'/'+c.total+' fields</div>';}function piiCell(a){const state=piiStateForAsset(a.id);if(state)return '<span class="pill pii-badge">'+esc(state.replace(/_/g,' '))+'</span>';if(a.is_pii===false)return '<span class="pill gray">Reviewed: not PII</span>';const m=a.metadata&&typeof a.metadata==='object'?a.metadata:{};const explicit=m.pii_classification||m.privacy_classification||m.sensitivity||m.classification;if(explicit)return '<span class="pill gray">'+esc(String(explicit).replace(/_/g,' '))+'</span>';return '<span class="pill gray">'+'Not classified'+'</span>';}function assetRows(list){return list.map(a=>'<tr><td><div class="asset-cell"><span class="asset-glyph '+a.kind+'">'+(a.kind==='source'?'▤':a.kind==='transform'?'⌘':'▣')+'</span><div><button class="inline-link" data-action="asset" data-id="'+a.id+'"><strong>'+esc(a.name)+'</strong></button><div class="subline">'+esc(a.path)+'</div></div></div></td><td>'+esc(a.type)+'</td><td class="num">'+a.rows+'</td><td class="num">'+a.columns+'</td><td class="num">'+(a.quality==null?'—':a.quality+'%')+'</td><td>'+esc(a.owner)+'</td><td>'+piiCell(a)+'</td><td>'+completenessCell(a)+'</td><td><button class="btn small" data-action="asset" data-id="'+a.id+'">Details</button></td></tr>')}
function universalPersistedOverview(){  if(S.dataError)return head('Workspace overview','The connected catalog could not be read. No metadata is inferred while the source is unavailable.','<button class="btn primary" data-action="refresh">Retry connection</button>')+'<section class="panel"><div class="panel-body"><div class="empty-state"><strong>Source unavailable</strong><p>'+esc(S.dataError)+'</p><button class="btn" data-action="refresh">Retry</button></div></div></section>';
  const typeOf=a=>String(a.type||a.asset_type||a.metadata?.asset_type||a.kind||'Unclassified').trim()||'Unclassified';
  const types=[...new Set(A.map(typeOf))].sort((a,b)=>a.localeCompare(b,undefined,{sensitivity:'base'}));
  const sources=[...new Set(A.map(a=>a.source_system||a.metadata?.source_system||a.repository||a.metadata?.repository||a.namespace||a.metadata?.namespace).filter(Boolean).map(String))].sort((a,b)=>a.localeCompare(b,undefined,{sensitivity:'base'}));
  const discoveredFields=[...new Set(A.flatMap(a=>[...Object.keys(a),...Object.keys(a.metadata&&typeof a.metadata==='object'?a.metadata:{})]))].filter(k=>!['id','metadata','raw_payload','raw_event'].includes(k.toLowerCase())&&!/token|secret|password|credential/i.test(k)).sort((a,b)=>a.localeCompare(b,undefined,{sensitivity:'base'}));
  const relationshipTypes=[...new Set(E.map(e=>String(e[3]||e[4]?.type||e[4]?.relationship_type||'relationship')).filter(Boolean))].sort();
  const typeRows=types.map(t=>'<div class="metric-line"><span>'+esc(t)+'</span><strong>'+A.filter(a=>typeOf(a)===t).length+'</strong></div>').join('');
  const summary='<div class="grid-equal section-spacer">'+panel('Discovered asset types','<div class="panel-body">'+(typeRows||'<p class="small-note">No asset types have been discovered yet.</p>')+'</div>')+panel('Connected source metadata','<div class="panel-body">'+(sources.length?sources.map(s=>'<div class="metric-line"><span>'+esc(s)+'</span><span class="muted">Discovered source</span></div>').join(''):'<p class="small-note">No source-system identifier has been recorded. Assets are still shown below.</p>')+'</div>')+'</div>'
    +panel('Available metadata fields','<div class="panel-body"><p class="small-note">Fields are discovered from the records currently returned by the connector. This list is not a required schema.</p><div class="tag-cloud">'+(discoveredFields.length?discoveredFields.map(f=>'<span class="pill gray">'+esc(f.replace(/[_-]+/g,' '))+'</span>').join(' '):'No fields discovered yet')+'</div></div>');
  const metrics='<div class="stat-grid">'+metricLink('Assets discovered',A.length,'◫','Actual records returned by the active source','assets')+metricLink('Relationships',E.length,'↔','Stored links; their meaning follows the source relationship type','lineage')+metricLink('Asset types',types.length,'◇','Distinct types discovered, not a predefined category list','catalog')+metricLink('Metadata fields',discoveredFields.length,'▤','Distinct fields across returned records','catalog')+'</div>';
  const assetPanel=A.length?panel('Discovered assets',dynamicAssetTable(A.slice(0,12)),'Only returned records are listed. Unavailable fields are not fabricated.','<button class="panel-link" data-view="assets">Browse all assets →</button>'):'<section class="panel"><div class="panel-body"><div class="empty-state"><strong>Your workspace is ready for its first source</strong><p>No assets have been returned yet. Connect a source or import a supported metadata artifact. The workspace will display the types and fields it discovers, including types that are not known in advance.</p><div class="empty-state-actions"><a href="/ingestion.html" class="btn primary">Connect / import metadata</a><button class="btn ghost" data-action="refresh">Check source again</button></div></div></div></section>';
  const relationships=E.length?panel('Recorded relationships','<div class="panel-body"><p class="small-note">'+E.length+' relationships are available. Relationship labels are shown as recorded; containment, references and data-flow lineage are not treated as interchangeable.</p><div class="tag-cloud">'+(relationshipTypes.length?relationshipTypes.map(t=>'<span class="pill gray">'+esc(t)+' · '+E.filter(e=>String(e[3]||e[4]?.type||e[4]?.relationship_type||'relationship')===t).length+'</span>').join(' '):'<span class="pill gray">Relationship type not recorded</span>')+'</div><button class="btn" data-view="lineage">Explore relationships</button></div>') : '';
  return head('Workspace overview','A source-adaptive view of the metadata actually returned by your connected systems.','<button class="btn ghost" data-action="refresh">Refresh source</button><a class="btn primary" href="/ingestion.html">Add / import source</a>')+metrics+assetPanel+summary+relationships;
}
function persistedOverview(){return universalPersistedOverview();}
function legacyPersistedOverview(){if(S.dataError)return head('Metadata overview','The persisted catalog could not be loaded. No catalog counts are available until the request succeeds.','<button class="btn primary" data-action="refresh">Retry catalog request</button>')+'<section class="panel"><div class="panel-body"><div class="empty-state"><strong>Catalog request failed</strong><p>'+esc(S.dataError)+'</p><p>This is a loading or access error, not evidence that the catalog is empty. The current catalog endpoint requires an authorized admin session.</p><button class="btn" data-action="refresh">Try again</button></div></div></section>';return head('Metadata overview','A live read of the persisted Kairos catalog. Counts below come from the PostgreSQL catalog API.','<button class="btn ghost" data-action="refresh">Refresh</button><button class="btn primary" data-view="lineage">Explore lineage</button>')+'<div class="stat-grid">'+card('Persisted assets',A.length,'▤','Rows returned by catalog API')+card('Stored lineage edges',E.length,'⌘','Stored relationships; not execution proof')+card('Pipeline runs',R.length,'↻','Persisted run records')+card('Evidence records',V.length,'◈','Persisted evidence rows')+'</div>'+(A.length?panel('Catalog assets',table(['Asset / schema','Type','Rows','Columns','Quality','Owner','PII classification','Metadata completeness',''],assetRows(A.slice(0,8))),'Persisted PostgreSQL records','<button class="panel-link" data-view="assets">View all</button>')+panel('Lineage preview','<div class="panel-body"><p class="small-note">Explore stored relationships in the 2D graph or interactive 3D warehouse. Edge presence alone does not establish runtime execution.</p><button class="btn" data-view="lineage">Open lineage explorer</button> <button class="btn primary" data-view="observatory">Open 3D observatory</button></div>'):'<section class="panel"><div class="panel-body"><div class="empty-state"><img src="/empty-state.png" alt="" aria-hidden="true" style="max-width:140px; margin-bottom:20px; opacity:0.85;"><strong>No metadata has been ingested yet</strong><p>Your PostgreSQL catalog is connected, but it contains no assets yet. Import a dbt manifest to add declared models and dependencies, or ingest OpenLineage events to add run and dataset evidence. Kairos will show only records actually stored here.</p><div class="empty-state-actions"><a href="/ingestion.html" class="btn primary">Import metadata</a><button class="btn ghost" data-action="refresh">Check again</button></div><small class="empty-state-footnote">No sample data has been mixed into this persisted catalog.</small></div></div></section>')}
    function overviewBase(){return persistedOverview()}
function homeOperationalPanel(){return '<div class="grid-equal section-spacer"><section class="panel"><div class="panel-head"><div><h2>Workspace health</h2><p>Counts reflect the latest API responses available to this page.</p></div><button class="panel-link" data-action="home-refresh">Refresh</button></div><div class="panel-body"><div id="homeHealthCards" class="stat-grid"><div class="empty-state">Loading governance status…</div></div><div id="homeSourceStatus" class="small-note">Checking configured sources…</div></div></section><section class="panel"><div class="panel-head"><div><h2>Recent pipeline runs</h2><p>Returned by the connected catalog API.</p></div><button class="panel-link" data-view="runs">All runs →</button></div><div class="panel-body" id="homeRecentRuns">'+(R.length?table(['Pipeline','Status','Started'],R.slice(0,5).map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+pill(x.status)+'</td><td>'+esc(x.start)+'</td></tr>')):'<div class="empty-state"><strong>No persisted pipeline runs</strong><p>No run rows were returned by the catalog API.</p></div>')+'</div></section></div><section class="panel section-spacer"><div class="panel-head"><div><h2>Quick actions</h2><p>Open a supported workspace workflow.</p></div></div><div class="panel-body"><div class="toolbar"><button class="btn primary" data-view="sources">Configure a source</button><a class="btn" href="/ingestion.html">Import metadata</a><button class="btn" data-view="lineage">Explore lineage</button><button class="btn" data-view="freshness">Review freshness</button><button class="btn" data-view="incidents">Open incidents</button></div><p class="small-note">Workspace-wide activity, notifications, PII change history, and ownership assignment require backend endpoints that are not available yet.</p></div></section>'}
async function loadHomeOperationalPanel(){const health=$('#homeHealthCards'),sourceBox=$('#homeSourceStatus');if(!health||!sourceBox)return;const requests=await Promise.allSettled([fetch('/api/v1/governance/freshness',{credentials:'same-origin',headers:{Accept:'application/json'}}),fetch('/api/v1/governance/incidents',{credentials:'same-origin',headers:{Accept:'application/json'}}),fetch('/api/v1/sources',{credentials:'same-origin',headers:{Accept:'application/json'}})]);const read=async result=>{if(result.status!=='fulfilled')throw result.reason;const response=result.value,data=await readApiPayload(response,'Workspace overview API');if(!response.ok)throw new Error(data.detail||data.error?.message||'API returned HTTP '+response.status);return data};try{const freshness=await read(requests[0]),incidents=await read(requests[1]),evaluations=freshness.evaluations||[],counts=freshness.counts||{},open=(incidents.incidents||[]).filter(x=>!['resolved','closed'].includes(String(x.status||'').toLowerCase())),critical=open.filter(x=>['critical','high'].includes(String(x.severity||'').toLowerCase()));const incidentRows=incidents.incidents||[],userId=window.kairosUser?.id,today=new Date().toDateString(),mine=open.filter(x=>userId&&String(x.owner_user_id||'')===String(userId)).length,resolvedToday=incidentRows.filter(x=>['resolved','closed'].includes(String(x.status||'').toLowerCase())&&x.resolved_at&&new Date(x.resolved_at).toDateString()===today).length;health.innerHTML='<h3>Freshness overview</h3><div class="stat-grid">'+metricLink('Evaluated assets',evaluations.length,'◇','Persisted evaluations','freshness')+metricLink('Healthy',counts.HEALTHY??0,'✓','Persisted evaluations','freshness')+metricLink('At risk',counts.AT_RISK??0,'!','Persisted evaluations','freshness')+metricLink('Late',counts.LATE??0,'!','Persisted evaluations','freshness')+metricLink('Unknown',counts.UNKNOWN??0,'?','No qualifying activity recorded','freshness')+'</div><h3 class="section-spacer">Incident summary</h3><div class="stat-grid">'+metricLink('Open',open.length,'⚠','Persisted incident rows','incidents')+metricLink('Critical / high',critical.length,'!','Open critical or high severity incidents','incidents')+metricLink('Assigned to me',mine,'◎','Owner matches signed-in user','incidents')+metricLink('Resolved today',resolvedToday,'✓','Persisted resolution timestamps','incidents')+'</div><div class="small-note">Freshness and incident counts come from authenticated API responses. Missing evaluations remain unknown.</div>'}catch(error){health.innerHTML='<div class="empty-state"><strong>Governance status unavailable</strong><p>'+esc(error.message||'The governance API could not be read.')+'</p></div>'}try{const sources=await read(requests[2]),rows=Array.isArray(sources)?sources:[],failed=rows.filter(x=>['ERROR','FAILED'].includes(String(x.lifecycle_state||'').toUpperCase()));sourceBox.innerHTML='<strong>'+rows.length+' configured sources</strong> · '+failed.length+' reporting an error'+(rows.length?'<div class="toolbar" style="margin-top:8px">'+rows.slice(0,4).map(x=>'<span class="pill '+(failed.includes(x)?'red':'gray')+'">'+esc(x.name)+' · '+esc(x.lifecycle_state)+'</span>').join('')+'</div>':' · No sources configured')+'<p class="small-note">Credential expiry, last incremental sync, and permission gaps are not exposed by the current sources API.</p>'}catch(error){sourceBox.innerHTML='<div class="empty-state"><strong>Source health unavailable</strong><p>'+esc(error.message||'The sources API could not be read.')+'</p></div>'}}
function metadataAttentionPanel(){const rows=A.map(a=>({asset:a,coverage:metadataCompleteness(a)})).sort((x,y)=>x.coverage.score-y.coverage.score);const complete=rows.filter(x=>!x.coverage.missing.length).length,partial=rows.filter(x=>x.coverage.score>=50&&x.coverage.missing.length).length,sparse=rows.filter(x=>x.coverage.score<50).length;const list=rows.filter(x=>x.coverage.missing.length).slice(0,5);const missingFields=[...new Set(rows.flatMap(x=>x.coverage.missing))].map(field=>({field,count:rows.filter(x=>x.coverage.missing.includes(field)).length})).filter(x=>x.count).sort((a,b)=>b.count-a.count);const source=S.dataMode==='demo'?'Sample metadata records; illustrative only.':'Loaded persisted catalog records; no synthetic records are added.';return `<section class="panel section-spacer"><div class="panel-head"><div><h2>Metadata attention</h2><p>Prioritize documentation gaps that make assets harder to discover and own.</p></div><span class="pill ${S.dataMode==='demo'?'blue':'mint'}">${S.dataMode==='demo'?'DEMO':S.catalogStatus==='ready'?'CONNECTED':S.catalogStatus==='error'?'ERROR':'CONNECTING'}</span></div><div class="panel-body"><div class="metadata-attention-metrics"><div class="metric-line"><span>Complete</span><strong>${complete}</strong></div><div class="metric-line"><span>Partial (50–99%)</span><strong>${partial}</strong></div><div class="metric-line"><span>Sparse (&lt;50%)</span><strong>${sparse}</strong></div></div><p class="small-note">Coverage is calculated from common asset fields and metadata keys discovered in this catalog. It is not a trust, certification, lineage, or data-quality score. ${source}</p>${missingFields.length?'<h3 class="metadata-attention-subhead">Most common gaps</h3><div class="reasoning-list metadata-attention-gaps">'+missingFields.slice(0,6).map(x=>'<button class="reasoning-item" data-action="filter-missing-metadata" data-field="'+esc(x.field)+'"><strong>'+esc(x.field)+'</strong><span class="pill amber">'+x.count+' assets</span></button>').join('')+'</div>':''}${list.length?`<div class="reasoning-list metadata-attention-assets">${list.map(x=>`<div class="reasoning-item"><div class="reason-head"><button class="inline-link" data-action="asset" data-id="${esc(x.asset.id)}"><strong>${esc(x.asset.path||x.asset.name)}</strong></button><span class="pill ${x.coverage.score<50?'amber':'blue'}">${x.coverage.score}% documented</span></div><p>Missing: ${esc(x.coverage.missing.join(', '))}</p></div>`).join('')}</div>`:'<div class="empty-state"><strong>No documentation gaps found in loaded records</strong><p>Presence of these fields does not certify the asset.</p></div>'}<div class="empty-state-actions"><button class="btn primary" data-action="show-metadata-attention">Review assets needing metadata</button></div></div></section>`;}function governanceHandoffPanel(){const fields=[['Owner','Ownership gaps','Find assets without a recorded owner.'],['Steward','Stewardship gaps','Find assets without a recorded steward.'],['Glossary','Glossary gaps','Find assets without a glossary term.']];const counts=fields.map(([field,title,desc])=>({field,title,desc,count:A.filter(a=>metadataCompleteness(a).missing.includes(field)).length})).filter(x=>x.count>0);return '<section class="panel section-spacer"><div class="panel-head"><div><h2>Governance handoff</h2><p>Route ownership and definition gaps to a focused review queue.</p></div><span class="pill">'+(S.dataMode==='demo'?'DEMO':S.catalogStatus==='ready'?'CONNECTED':S.catalogStatus==='error'?'ERROR':'CONNECTING')+'</span></div><div class="panel-body"><div class="reasoning-list">'+(counts.length?counts.map(x=>'<div class="reasoning-item"><div class="reason-head"><strong>'+x.title+'</strong><span class="pill amber">'+x.count+' assets</span></div><p>'+x.desc+'</p><button class="btn small" data-action="filter-missing-metadata" data-field="'+x.field+'">Review matching assets</button></div>').join(''):'<div class="empty-state"><strong>No owner, steward, or glossary gaps in loaded records</strong><p>Presence in this checklist is not governance approval or certification.</p></div>')+'</div><p class="small-note">Counts are based on loaded catalog metadata. Review actions filter assets; they do not approve policies or write metadata.</p></div></section>';}function catalogPage(){return catalogPageBase()+governanceHandoffPanel();}function welcomeGreeting(){let fullName=(localStorage.getItem('kairos_workspaceLabel')||localStorage.getItem('kairos_profileName')||'Research workspace').trim();if(!fullName||/^(workspace|workspace user|user|there)$/i.test(fullName))fullName='Jatin Shende';const greetingName=fullName;/*full workspace label*/const firstName=fullName.split(/\s+/).filter(Boolean)[0]||'there';return '<section class="welcome-greeting" aria-label="Welcome"><p>WELCOME BACK</p><h1>Hi, '+esc(greetingName)+' 👋</h1><span>Your metadata workspace at a glance.</span></section>';}function overview(){return welcomeGreeting()+overviewBase()+homeOperationalPanel()+metadataAttentionPanel()+governanceHandoffPanel();}
function assetFacetValue(a,key){const m=a.metadata&&typeof a.metadata==='object'?a.metadata:{};if(key==='domain')return String(m.domain||m.business_domain||a.domain||m.repository||a.repository||m.source_system||a.source_system||m.namespace||a.schema||'').trim();if(key==='type')return String(a.type||a.asset_type||m.asset_type||a.kind||'Unclassified').trim();if(key==='owner')return String(a.owner||m.owner||a.owner_name||'').trim();if(key==='platform')return String(a.platform||a.source_system||m.platform||m.source_system||m.connector||m.service_name||'').trim();if(key==='environment')return String(a.environment||a.env||m.environment||m.env||'').trim();if(key==='tag'){const v=m.tags||m.labels||m.topics||a.tags||a.labels||a.topics||(S.dataMode==='demo'?['active','production']:[]);return (Array.isArray(v)?v:[v]).map(x=>String(typeof x==='object'?(x.name||x.value||x.label||''):x||'').trim()).filter(Boolean)}if(key==='trust'){const v=m.trust_status||m.trust||m.certification_status||m.certification||a.trust_status||a.trust;return v==null||String(v).trim()===''?'':String(v).trim()}return '';}
function assetFacetOptions(key){const vals=new Set();A.forEach(a=>{const v=assetFacetValue(a,key);(Array.isArray(v)?v:[v]).forEach(x=>{if(x)vals.add(x)})});return [...vals].sort((a,b)=>a.localeCompare(b,undefined,{sensitivity:'base'}));}
function filteredCatalogAssets(){const resetIfMissing=(key,facet)=>{if(S[key]!=='all'&&!assetFacetOptions(facet).includes(S[key]))S[key]='all'};resetIfMissing('assetFilter','type');resetIfMissing('assetDomain','domain');resetIfMissing('assetOwner','owner');resetIfMissing('assetPlatform','platform');resetIfMissing('assetEnvironment','environment');resetIfMissing('assetTag','tag');if(S.assetTrust!=='all'&&S.assetTrust!=='__unknown__'&&!assetFacetOptions('trust').includes(S.assetTrust))S.assetTrust='all';const availableMissing=new Set(A.flatMap(a=>metadataCompleteness(a).missing));if(S.assetMissingField&&S.assetMissingField!=='all'&&!availableMissing.has(S.assetMissingField))S.assetMissingField='all';const q=S.assetSearch.trim().toLowerCase();const rows=A.filter(a=>{const m=a.metadata&&typeof a.metadata==='object'?a.metadata:{},tags=assetFacetValue(a,'tag'),trust=assetFacetValue(a,'trust'),columns=m.columns&&typeof m.columns==='object'?Object.entries(m.columns).flatMap(([name,col])=>[name,typeof col==='object'?col.type:'',typeof col==='object'?col.description:'']):[],hay=[a.name,a.path,a.owner,a.schema,a.type,a.kind,a.description,a.platform,a.environment,m.description,m.glossary,m.namespace,m.repository,m.source_system,m.connector,m.platform,...columns,...tags].filter(Boolean).join(' ').toLowerCase();return(S.assetFilter==='all'||assetFacetValue(a,'type')===S.assetFilter||a.kind===S.assetFilter)&&(S.assetDomain==='all'||assetFacetValue(a,'domain')===S.assetDomain)&&(S.assetOwner==='all'||assetFacetValue(a,'owner')===S.assetOwner)&&(S.assetPlatform==='all'||assetFacetValue(a,'platform')===S.assetPlatform)&&(S.assetEnvironment==='all'||assetFacetValue(a,'environment')===S.assetEnvironment)&&(S.assetTag==='all'||tags.includes(S.assetTag))&&(S.assetTrust==='all'||(S.assetTrust==='__unknown__'?!trust:trust===S.assetTrust))&&((S.assetCompleteness||'all')==='all'||(S.assetCompleteness==='needs'&&metadataCompleteness(a).missing.length>0)||(S.assetCompleteness==='sparse'&&metadataCompleteness(a).score<50)||(S.assetCompleteness==='complete'&&metadataCompleteness(a).missing.length===0))&&((!S.assetMissingField||S.assetMissingField==='all')||metadataCompleteness(a).missing.includes(S.assetMissingField))&&(!q||hay.includes(q))});const updated=a=>a.updated_at||a.updatedAt||a.last_updated||a.metadata?.updated_at||a.metadata?.last_updated||a.metadata?.last_seen||null,usage=a=>Number(a.usage_count??a.metadata?.usage_count??a.metadata?.usage?.weekly_views??a.metadata?.usage?.views??NaN);const sorters={'name-asc':(a,b)=>(a.path||a.name).localeCompare(b.path||b.name,undefined,{sensitivity:'base'}),'name-desc':(a,b)=>(b.path||b.name).localeCompare(a.path||a.name,undefined,{sensitivity:'base'}),'owner-asc':(a,b)=>assetFacetValue(a,'owner').localeCompare(assetFacetValue(b,'owner'),undefined,{sensitivity:'base'}),'domain-asc':(a,b)=>assetFacetValue(a,'domain').localeCompare(assetFacetValue(b,'domain'),undefined,{sensitivity:'base'}),'columns-desc':(a,b)=>(Number(b.columns)||0)-(Number(a.columns)||0),'trust-asc':(a,b)=>assetFacetValue(a,'trust').localeCompare(assetFacetValue(b,'trust'),undefined,{sensitivity:'base'}),'updated-desc':(a,b)=>(Date.parse(updated(b))||0)-(Date.parse(updated(a))||0),'usage-desc':(a,b)=>(usage(b)||0)-(usage(a)||0)};return rows.sort(sorters[S.assetSort]||sorters['name-asc']);}
function savedCatalogViews(){try{const rows=JSON.parse(localStorage.getItem('kairos_catalogViews')||'[]');return Array.isArray(rows)?rows.filter(x=>x&&typeof x.id==='string'&&typeof x.name==='string'&&x.filters&&typeof x.filters==='object'):[]}catch(_){return []}}function catalogViewFilters(){return Object.fromEntries(['assetSearch','assetFilter','assetDomain','assetOwner','assetPlatform','assetEnvironment','assetTag','assetTrust','assetSort','assetCompleteness','assetMissingField'].map(k=>[k,S[k]??'all']))}function catalogFilterToolbarBase(rows,sourceLabel){const select=(id,label,allLabel,values,selected)=>'<label class="field"><span>'+label+'</span><select id="'+id+'" aria-label="'+label+'"><option value="all">'+allLabel+'</option>'+values.map(v=>'<option value="'+esc(v)+'" '+(selected===v?'selected':'')+'>'+(id==='assetTrust'&&v==='__unknown__'?'Unknown / not recorded':esc(v))+'</option>').join('')+'</select></label>';const facet=(key,id,label,all)=>{const values=assetFacetOptions(key);return values.length?select(id,label,all,values,S[id==='assetPlatform'?'assetPlatform':'assetEnvironment']):''};const trusts=assetFacetOptions('trust');if(A.some(a=>!assetFacetValue(a,'trust')))trusts.push('__unknown__');const sorts=[['name-asc','Name (A–Z)'],['name-desc','Name (Z–A)'],['owner-asc','Owner'],['domain-asc','Domain / schema'],['columns-desc','Column count (high to low)'],['trust-asc','Trust status']];if(A.some(a=>a.updated_at||a.updatedAt||a.last_updated||a.metadata?.updated_at||a.metadata?.last_updated||a.metadata?.last_seen))sorts.push(['updated-desc','Last updated']);if(A.some(a=>Number.isFinite(Number(a.usage_count??a.metadata?.usage_count??a.metadata?.usage?.weekly_views??a.metadata?.usage?.views))))sorts.push(['usage-desc','Usage']);const views=savedCatalogViews(),viewSelect='<label class="field"><span>Saved views · this browser</span><select id="assetSavedView" aria-label="Load a browser-local saved asset view"><option value="">Choose saved view…</option>'+views.map(v=>'<option value="'+esc(v.id)+'" '+(Object.entries(v.filters).every(([k,value])=>(S[k]??(k==='assetSearch'?'':'all'))===value)?'selected':'')+'>'+esc(v.name)+'</option>').join('')+'</select></label>';return '<div class="toolbar"><label class="search-box"><span aria-hidden="true">⌕</span><input id="assetSearch" aria-label="Search assets by name, schema, description, columns, owner, or tags" value="'+esc(S.assetSearch)+'" placeholder="Search asset, description, columns, owner or tag"></label>'+select('assetFilter','Asset type','All asset types',assetFacetOptions('type'),S.assetFilter)+select('assetDomain','Domain / schema','All domains',assetFacetOptions('domain'),S.assetDomain)+select('assetOwner','Owner','All owners',assetFacetOptions('owner'),S.assetOwner)+facet('platform','assetPlatform','Platform','All platforms')+facet('environment','assetEnvironment','Environment','All environments')+select('assetTag','Tag','All tags',assetFacetOptions('tag'),S.assetTag)+select('assetTrust','Trust status','All trust states',trusts,S.assetTrust)+'<label class="field"><span>Sort by</span><select id="assetSort" aria-label="Sort assets">'+sorts.map(([v,l])=>'<option value="'+v+'" '+(S.assetSort===v?'selected':'')+'>'+l+'</option>').join('')+'</select></label></div><div class="toolbar">'+viewSelect+'<button class="btn small" data-action="save-catalog-view">Save current view</button><button class="btn small" data-action="delete-catalog-view" '+(views.some(v=>Object.entries(v.filters).every(([k,value])=>(S[k]??(k==='assetSearch'?'':'all'))===value))?'':'disabled')+'>Delete selected view</button><span class="filter-count">'+rows.length+' '+sourceLabel+' assets shown · '+A.length+' total</span><button class="btn small" data-action="clear-asset-filters">Clear filters</button></div>';}
function catalogFilterToolbar(rows,sourceLabel){const fields=[...new Set(A.flatMap(a=>metadataCompleteness(a).missing))].sort((a,b)=>a.localeCompare(b,undefined,{sensitivity:'base'}));return catalogFilterToolbarBase(rows,sourceLabel)+'<div class=\"toolbar\"><label class=\"field\"><span>Metadata coverage</span><select id=\"assetCompleteness\" aria-label=\"Filter by metadata completeness\"><option value=\"all\" '+((S.assetCompleteness||'all')==='all'?'selected':'')+'>Any coverage</option><option value=\"needs\" '+(S.assetCompleteness==='needs'?'selected':'')+'>Needs metadata</option><option value=\"sparse\" '+(S.assetCompleteness==='sparse'?'selected':'')+'>Sparse (&lt;50%)</option><option value=\"complete\" '+(S.assetCompleteness==='complete'?'selected':'')+'>All discovered fields recorded</option></select></label><label class=\"field\"><span>Missing field</span><select id=\"assetMissingField\" aria-label=\"Filter by missing metadata field\"><option value=\"all\">Any missing field</option>'+fields.map(field=>'<option value=\"'+esc(field)+'\" '+(S.assetMissingField===field?'selected':'')+'>'+esc(field)+'</option>').join('')+'</select></label></div>';}
