async function openPersistedEdgeEvidence(edgeId,source,target,relationshipType){
  const label=(source?.path||source?.name||'Unknown source')+' → '+(target?.path||target?.name||'Unknown target');
  modal('Loading stored edge evidence','<div class="empty-state"><strong>Loading evidence</strong><p>'+esc(label)+'</p></div>');
  try{
    const response=await fetch('/api/v1/lineage/edges/'+encodeURIComponent(edgeId)+'/evidence',{credentials:'same-origin',headers:{Accept:'application/json'}});
    if(!response.ok)throw new Error(response.status===404?'This edge or its evidence is no longer available.':'Evidence request failed ('+response.status+').');
    const result=await response.json(),records=Array.isArray(result.evidence)?result.evidence:[],time=value=>value?esc(value):'Not recorded';
    const rows=records.map(item=>{
      const valid=item.valid_time||{},recorded=item.recorded_time||{},provenance=item.provenance||{};
      const raw=provenance.raw_available?'<details><summary>Sanitized raw event</summary><pre class="github-file-preview">'+esc(JSON.stringify(provenance.raw,null,2))+'</pre></details>':'<p class="small-note">No raw event is attached to this evidence.</p>';
      return '<article class="reasoning-item"><div class="reason-head"><strong>'+esc(item.evidence_id||item.evidence_row_id||'Evidence record')+'</strong>'+pill(item.state||'UNKNOWN')+'</div>'+
        '<div class="metric-line"><span>Evidence source</span><strong>'+esc(item.source_system||'Not recorded')+'</strong></div>'+
        '<div class="metric-line"><span>Evidence type</span><strong>'+esc(item.evidence_type||'Not recorded')+'</strong></div>'+
        '<div class="metric-line"><span>Run</span><strong>'+esc(item.run_id||'Not run-scoped')+'</strong></div>'+
        '<div class="metric-line"><span>Coverage</span><strong>'+esc(JSON.stringify(item.coverage??'Not recorded'))+'</strong></div>'+
        '<div class="metric-line"><span>Rule-derived strength</span><strong>'+esc(item.strength||'Low')+'</strong></div>'+
        '<div class="metric-line"><span>Valid time</span><strong>'+time(valid.from)+' → '+time(valid.to)+' ('+esc(valid.status||'UNKNOWN')+')</strong></div>'+
        '<div class="metric-line"><span>Recorded time</span><strong>'+time(recorded.from)+' → '+time(recorded.to)+'</strong></div>'+
        '<p class="small-note">'+esc(stateInterpretation(item.state))+'</p><p>'+esc(item.explanation||'No explanation was stored.')+'</p><details><summary>Provenance chain · '+esc(provenance.parser?.adapter||'parser not recorded')+'</summary><div class="metric-line"><span>Adapter version</span><strong>'+esc(provenance.parser?.adapter_version||'Not recorded')+'</strong></div><pre class="github-file-preview">'+esc(JSON.stringify({normalized:provenance.normalized,canonical:provenance.canonical},null,2))+'</pre></details>'+raw+'</article>';
    }).join('');
    const conflict=result.conflict?'<div class="notice warning"><strong>Conflicting evidence states</strong><p>Both OBSERVED and REFUTED_FOR_RUN evidence are recorded for '+esc((result.conflicting_runs||[]).join(', ')||'one or more runs')+'. The refutation is run-scoped.</p></div>':'';
    const empty=records.length?'':'<div class="empty-state"><strong>No evidence attached</strong><p>The stored relationship exists, but there are no evidence rows to support an execution claim.</p></div>';
    modal('Lineage relationship evidence','<div class="node-detail"><h3>'+esc(label)+'</h3><div class="metric-line"><span>Relationship type</span><strong>'+esc(relationshipType||result.granularity||'Not recorded')+'</strong></div><p class="small-note">Stored edge presence alone does not prove execution. Strength is an ordinal rule label, not a probability.</p>'+conflict+(result.truncated?'<p class="small-note">Evidence list capped at 500 records.</p>':'')+empty+rows+'</div>');
  }catch(error){modal('Evidence could not be loaded','<div class="empty-state"><strong>Stored evidence request failed</strong><p>'+esc(error.message||'Request failed.')+'</p><p class="small-note">The graph edge remains visible, but this view will not substitute local fixture evidence.</p></div>')}
}
