function trackUX(event,properties={}){try{if(window.posthog&&typeof window.posthog.capture==='function')window.posthog.capture(event,{app:'kairos',...properties})}catch(_){/* Analytics must never interrupt the workspace. */}}
window.generateIntegrationToken = function() {
  toast('API token issuance is not configured. No credential was created.');
};
window.copyIntegrationToken = function() {
  const tokenInput = document.getElementById('integrationTokenVal');
  if (tokenInput && tokenInput.value) {
    navigator.clipboard.writeText(tokenInput.value);
    const btn = document.getElementById('copyTokenBtn');
    if (btn) {
      btn.textContent = 'Copied!';
      setTimeout(() => { btn.textContent = 'Copy'; }, 2000);
    }
  }
};
function integrationsPage() {
  return head('Integrations & API', 'Browse source files and inspect what Kairos can import into this workspace.', '') +
    '<section class="panel github-connector-panel"><div class="panel-head"><div><h2>GitHub repository browser</h2><p>Explore a public repository, preview source files, and download a selected file.</p></div><span class="pill blue">PUBLIC REPOS</span></div><div class="panel-body">' +
    '<div class="github-connector-note"><strong>Access boundary</strong><p>GitHub sign-in to Kairos does not grant repository access. This browser currently reads public repositories only and does not save files or metadata into the catalog. Private repository access needs a separately configured GitHub App with read-only permissions.</p></div>' +
    '<form id="githubRepoForm" class="github-repo-form"><label class="field"><span>Repository</span><input id="githubRepoInput" autocomplete="url" placeholder="owner/repository (for example, open-metadata/OpenMetadata)" required pattern="[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+" aria-describedby="githubRepoHelp"></label><label class="field github-branch-field"><span>Branch <small>(optional)</small></span><input id="githubBranchInput" autocomplete="off" placeholder="Default branch"></label><button class="btn primary" id="githubBrowseButton" type="submit">Browse repository</button></form>' +
    '<p class="small-note" id="githubRepoHelp">Kairos requests only public repository metadata and file contents for this preview.</p><div id="githubRepoResults" class="github-repo-results" aria-live="polite"></div>' +
    '</div></section>' +
    '<section class="panel" style="margin-top:20px;"><div class="panel-head"><div><h2>Private repository connection</h2><p>Planned connector capability; OAuth App/GitHub App credentials and secure token storage are not configured in this project yet.</p></div></div><div class="panel-body"><p class="small-note">The research report recommends read-only repository access: repository metadata and contents. A GitHub App can let a user or organization select which repositories Kairos may access.</p></div></section>';
}

