    '<div id="testGeneratorSection" style="margin-top:20px;"><h4 style="margin-bottom:8px; font-weight:700;">Step 2: Recommended Test Definition Suite</h4><p class="small-note" style="margin-bottom:12px;">Synthesized from column schema and lineage dependencies.</p><div class="reasoning-list" style="margin-bottom:16px;">' +
    suggestedTests.map(t => '<div class="reasoning-item" style="padding:10px 14px;"><div class="reason-head"><strong>' + esc(t.name) + '</strong><span class="pill blue">' + esc(t.type) + '</span></div><p style="margin:4px 0 0; font-size:0.82rem;">' + esc(t.desc) + ' (Target: <code class="mono">' + esc(t.col) + '</code>)</p></div>').join('') +
    '</div><details style="margin-bottom:16px; background:var(--surface,#1f2937); border:1px solid var(--line,#374151); border-radius:8px; padding:10px 14px;"><summary style="font-weight:600; cursor:pointer; font-size:0.88rem; color:var(--ink,#e5e7eb);">View Generated YAML Test Definition Spec</summary><pre style="margin-top:8px; padding:10px; background:#0d1117; border:1px solid #30363d; border-radius:6px; font-family:var(--font-mono,monospace); font-size:11px; color:#58a6ff; overflow-x:auto;">' + esc(generatedYaml) + '</pre></details></div>' +
    '<div style="display:flex; justify-content:flex-end; gap:10px; margin-top:24px; padding-top:16px; border-top:1px solid var(--line,#374151);"><button class="btn" onclick="document.getElementById(\'modalBackdrop\').hidden=true">Cancel</button><button class="btn primary" id="btnApplyTriage" data-asset="' + esc(asset.path || asset.name) + '">Add demo recommendations</button></div>';
  modal('Data Steward Triage & Auto-Generate Tests', body);
