function attachGraphTooltips(){$$('[data-node]').forEach(n=>{const id=n.getAttribute('data-id'),a=A.find(x=>x.id===id);if(!a)return;n.addEventListener('mouseenter',()=>{if(n._t)return;const t=document.createElement('div');t.className='graph-tooltip';t.textContent=a.name+' ('+a.rows+' rows)';n.parentElement?.appendChild(t);n._t=t;setTimeout(()=>t.classList.add('visible'),10)});n.addEventListener('mouseleave',()=>{if(n._t){n._t.classList.remove('visible');setTimeout(()=>{n._t?.remove();n._t=null},150)}})})};/* Phase 2: Sidebar state on load */
